"""Offline whole-run lanes with independently compressed iteration details.

All numerical demand is supplied by the existing recorder/production owners.
This view only aggregates intervals and normalizes supplied work by capacities.
"""
from __future__ import annotations

import base64
import gzip
import hashlib
import json
import math
from pathlib import Path
import time

from evaluation.reporting.serving_interactive import (
    _HTML, _pack_projection, _safe_plan, _safe_predictions, _safe_timeline,
    _unpack_projection, _pack_summary_projection, _safe_report_metadata, _validate_diagnostics,
    _report_json_bytes,
)
from src.kernel.resource_usage import report_memory_bandwidth_reference
from evaluation.reporting.serving_viewer_ui import with_serving_viewer_ui, report_experiment_configuration, report_run_context, _configuration_metadata


def write_iteration_chunk(step, resources, diagnostics, directory, index):
    """Write one request-safe forward without retaining full-run IR in memory."""
    row = {name: step[name] for name in ("step_id", "pool_name", "schedule_interval", "timing")}
    row["requests"] = [{name: request[name] for name in (
        "request_id", "phase", "input_tokens", "output_tokens")}
        for request in step["backend_step"]["schedule"]["requests"]]
    row["kernel_plan"] = _safe_plan(step["kernel_plan"])
    row["execution_timeline"] = _safe_timeline(step["execution_timeline"])
    row["predictions"] = _safe_predictions(step["predictions"]) if "predictions" in step else []
    chunk = {"step": row, "resources": resources, "diagnostics": diagnostics}
    encoded = gzip.compress(json.dumps(_pack_projection(chunk), separators=(",", ":"),
        allow_nan=False).encode(), compresslevel=6, mtime=0)
    directory = Path(directory)
    directory.mkdir(parents=True, exist_ok=True)
    path = directory / f"iteration-{index:06d}.json.gz"
    with path.open("xb") as stream:
        stream.write(encoded)
    return {"step_id": row["step_id"], "file": path.name,
        "sha256": hashlib.sha256(encoded).hexdigest(), "bytes": len(encoded)}


def _iterations(payload):
    if "visualization_iterations" in payload:
        return payload["visualization_iterations"]
    # Legacy projections have every envelope, but request metadata only for samples.
    details = {step["step_id"]: step for step in payload["execution_artifact"]["steps"]}
    result = {}
    for row in payload["visualization_summary"]:
        if row["phases"] == ["kv_handoff"]:
            continue
        key = row["step_id"]
        if key not in result:
            result[key] = {"step_id": key, "pool_name": row["pool_name"],
                "device_start_time_s": row["start_time_s"], "device_end_time_s": row["end_time_s"],
                "phases": row["phases"], "requests": (details[key]["backend_step"]["schedule"]["requests"]
                    if key in details else None)}
        else:
            result[key]["device_start_time_s"] = min(result[key]["device_start_time_s"], row["start_time_s"])
            result[key]["device_end_time_s"] = max(result[key]["device_end_time_s"], row["end_time_s"])
    return list(result.values())


def write_swimlane_report(payload, output, *, selected_step_ids=None):
    """Stream a standalone HTML; decode only the selected forward in the browser."""
    started = time.perf_counter()
    payload = _unpack_projection(payload)
    output = Path(output)
    output.parent.mkdir(parents=True, exist_ok=True)
    diagnostics = payload["visualization_diagnostics"] if "visualization_diagnostics" in payload else None
    _validate_diagnostics(diagnostics, payload["visualization_summary"])
    if "visualization_detail_archive" in payload:
        archive = payload["visualization_detail_archive"]
    else:
        directory = output.with_suffix(".iterations")
        records = []
        for index, step in enumerate(payload["execution_artifact"]["steps"]):
            ids = {call["call_id"] for call in step["kernel_plan"]["calls"]}
            resources = ({key: value for key, value in payload["visualization_resources"].items() if key in ids}
                if payload["visualization_resources"] is not None else None)
            local = ({name: {key: value for key, value in diagnostics[name].items() if key in ids}
                for name in ("by_call_id", "missing_by_call_id")} if diagnostics is not None else None)
            record = write_iteration_chunk(step, resources, local, directory, index)
            records.append({**record, "delta_s": 0.0})
        archive = {"directory": str(directory.resolve()), "records": records}
    records = [record for record in archive["records"]
        if selected_step_ids is None or record["step_id"] in selected_step_ids]
    available = {record["step_id"]: index for index, record in enumerate(records)}
    if len(available) != len(records):
        raise ValueError("duplicate iteration detail ID")
    iterations = _iterations(payload)
    if set(available) - {row["step_id"] for row in iterations}:
        raise ValueError("iteration detail is absent from the whole-run index")
    coverage = dict(payload["visualization_coverage"])
    selected_iterations = [row for row in iterations if row["step_id"] in available]
    covered_requests = {request["request_id"] for row in selected_iterations
        if row["requests"] is not None for request in row["requests"]}
    coverage["detailed_steps"] = len(records)
    coverage["detailed_requests"] = len(covered_requests)
    coverage["total_steps"] = len(iterations)
    if all("event_count" in row for row in selected_iterations):
        coverage["detail_events"] = sum(row["event_count"] for row in selected_iterations)
        coverage["omitted_detail_events"] = coverage["total_events"] - coverage["detail_events"]
    coverage["selection"] = ("compact summary; no operator details" if coverage["activity_availability"] == "unavailable" else "all forwards" if len(records) == len(iterations) else "selected forward samples") if "activity_availability" in coverage else ("all forwards" if len(records) == len(iterations) else "selected forward samples")
    intervals = []
    for row in sorted(selected_iterations, key=lambda item: item["device_start_time_s"]):
        start, end = row["device_start_time_s"], row["device_end_time_s"]
        if intervals and start <= intervals[-1][1]:
            intervals[-1][1] = max(intervals[-1][1], end)
        else:
            intervals.append([start, end])
    coverage["detail_intervals_s"] = intervals
    coverage["detail_interval_s"] = [intervals[0][0], intervals[-1][1]] if intervals else None
    catalog = diagnostics["critical_paths"] if diagnostics is not None else None
    # A homogeneous report has one unambiguous device peak reference. Mixed
    # hardware reports retain their supplied per-row capacities until their
    # summary contract supplies a hardware identity for every lane.
    hardware_ids = list(payload["visualization_hardware"])
    bandwidth_reference = (payload["visualization_memory_bandwidth_reference"]
        if "visualization_memory_bandwidth_reference" in payload else
        report_memory_bandwidth_reference(hardware_ids[0]) if len(hardware_ids) == 1 else None)
    if bandwidth_reference is not None:
        if set(bandwidth_reference) != {"l2", "hbm"}:
            raise ValueError("invalid memory bandwidth reference resources")
        for role in ("l2", "hbm"):
            peak = bandwidth_reference[role]
            if peak["combined"] not in ("max_directional", "shared_sum"):
                raise ValueError("invalid memory bandwidth combined policy")
            read, write = peak["read_bytes_per_second"], peak["write_bytes_per_second"]
            if not all(math.isfinite(value) and value > 0 for value in (read, write)):
                raise ValueError("invalid memory bandwidth peak")
            if peak["combined"] == "shared_sum" and read != write:
                raise ValueError("shared bandwidth requires equal directional denominators")
            if not peak["basis"] or not peak["source"]:
                raise ValueError("missing memory bandwidth reference provenance")
    data = {"iterations": iterations, "detail_index": available,
        "memory_bandwidth_reference": bandwidth_reference,
        "cost_receipt_path": payload["visualization_cost_receipt_path"] if "visualization_cost_receipt_path" in payload else None,
        "run_context": report_run_context(payload, coverage),
        "experiment_configuration": report_experiment_configuration({**payload, "visualization_memory_bandwidth_reference": bandwidth_reference}),
        "detail_delta_s": {record["step_id"]: record["delta_s"] for record in records},
        "summary": payload["visualization_summary"], "schedule": payload["visualization_schedule"],
        "links": payload["visualization_links"], "hardware": payload["visualization_hardware"],
        "capacity": payload["kv_capacity"] if "kv_capacity" in payload else None, "metrics": payload["metrics"],
        "end_s": payload["schedule_end_time_s"], "simulation_wall_time_s": payload["simulation_wall_time_s"],
        "prediction_method": payload["prediction_method"], "launch_policy": payload["launch_policy"],
        "critical_paths": catalog, "coverage": coverage,
        "source_activation_memory": payload["source_activation_memory"] if "source_activation_memory" in payload else None,
        "transfer_metadata": payload["visualization_transfer_metadata"] if "visualization_transfer_metadata" in payload else [],
        "transfer_summary": payload["visualization_transfer_summary"] if "visualization_transfer_summary" in payload else None,
        "routing": payload["execution_artifact"]["schedule_trace"]["route_decisions"]}
    compression_started = time.perf_counter()
    serialized_values = {id(data[name]): (data[name], None) for name in (
        "iterations", "summary", "schedule", "source_activation_memory")
        if type(data[name]) in (dict, list, tuple)}
    # Favor lower total CPU work for concurrent experiments. The browser still
    # decodes the exact same overview; only the gzip size/CPU tradeoff changes.
    overview = base64.b64encode(gzip.compress(_report_json_bytes(data, serialized_values),
        compresslevel=1, mtime=0)).decode()
    # The detail viewer is the same implementation used by existing reports.
    template = json.dumps(with_serving_viewer_ui(_HTML), ensure_ascii=True).replace("<", "\\u003c")
    prefix, suffix = with_serving_viewer_ui(_SWIMLANES).replace("__OVERVIEW__", overview).replace("__VIEWER_TEMPLATE__", template).split("__CHUNKS__")
    compression_s = time.perf_counter() - compression_started
    html_started = time.perf_counter()
    directory = Path(archive["directory"]).resolve()
    chunk_bytes = 0
    with output.open("w") as stream:
        stream.write(prefix)
        for index, record in enumerate(records):
            path = (directory / record["file"]).resolve()
            if not path.is_relative_to(directory):
                raise ValueError("iteration detail path escapes archive directory")
            encoded = path.read_bytes()
            if len(encoded) != record["bytes"] or hashlib.sha256(encoded).hexdigest() != record["sha256"]:
                raise ValueError("iteration detail content does not match archive index")
            stream.write(f'<script type="application/octet-stream" id="chunk-{index}">')
            stream.write(base64.b64encode(encoded).decode())
            stream.write('</script>\n')
            chunk_bytes += len(encoded)
        stream.write(suffix)
    html_write_s = time.perf_counter() - html_started
    json_started = time.perf_counter()
    replaced_fields = {"transfers", "execution_artifact", "visualization_resources",
        "visualization_diagnostics", "visualization_detail_archive", "visualization_iterations",
        "visualization_coverage", "visualization_view", "visualization_memory_bandwidth_reference"}
    safe = {**_safe_report_metadata({key: value for key, value in payload.items() if key not in replaced_fields}), "execution_artifact": {"steps": [], "transfers": [],
        "schedule_trace": {"route_decisions": data["routing"]}},
        "visualization_resources": {}, "visualization_diagnostics": ({**diagnostics,
            "by_call_id": {}, "missing_by_call_id": {}} if diagnostics is not None else None),
        "visualization_detail_archive": {"directory": str(directory), "records": records},
        "visualization_iterations": iterations, "visualization_coverage": coverage, "visualization_view": "swimlanes",
        "visualization_memory_bandwidth_reference": bandwidth_reference}
    data_path = output.with_suffix(".visualization.json")
    data_path.write_text(json.dumps(_pack_summary_projection(safe, serialized_values=serialized_values),
        separators=(",", ":"), allow_nan=False))
    costs = {"overview_compression_s": compression_s, "html_write_s": html_write_s,
        "projection_json_write_s": time.perf_counter() - json_started,
        "renderer_wall_s": time.perf_counter() - started,
        "scope": "renderer includes projection, compression, embedded chunk reads, HTML and JSON writes; recording is separate"}
    return {"render_costs": costs, "path": str(output), "data_path": str(data_path), "html_bytes": output.stat().st_size,
        "data_bytes": data_path.stat().st_size, "detail_compressed_bytes": chunk_bytes,
        "detail_steps": len(records), "total_steps": len(iterations),
        "page_generation_s": time.perf_counter() - started}


